        {/* Bottom gold shimmer line */}
        <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-gradient-to-r from-transparent via-gold-400/60 to-transparent" />
      </section>

      {/* ============ WELCOME SECTION ============ */}
      <section className="relative bg-white py-6 overflow-hidden">
