              className="font-serif text-3xl md:text-4xl lg:text-5xl xl:text-6xl font-bold text-white leading-tight drop-shadow-2xl"
            >
              {slide.title}
            </motion.h1>

            {/* Divider — Elegant Gold Line */}
            <motion.div
              initial={{ width: 0 }}
